<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CategoryController extends Controller {public function index(){return view('admin.categories.index',['items'=>Category::orderBy('sort_order')->paginate(30)]);}public function store(Request $r){$d=$r->validate(['name'=>'required|max:180','slug'=>'nullable|max:200|unique:categories,slug','description'=>'nullable','status'=>'required|in:active,inactive']);$d['slug']=$d['slug']?:Str::slug($d['name']);Category::create($d);return back()->with('success','Category created.');}public function update(Request $r,Category $category){$d=$r->validate(['name'=>'required|max:180','slug'=>'required|max:200|unique:categories,slug,'.$category->id,'description'=>'nullable','status'=>'required|in:active,inactive']);$category->update($d);return back()->with('success','Category updated.');}public function destroy(Category $category){$category->delete();return back()->with('success','Category deleted.');}}
